"""Build 06-scenes.md and prompts.csv from one scene table, expanding the continuity tokens from 04-continuity.md
so every prompt is copy-ready and identical in both files.  Run: python3 build_scenes.py"""
import csv, re, pathlib
HERE = pathlib.Path(__file__).parent
cont = (HERE / '04-continuity.md').read_text()
TOK = dict(re.findall(r'```\n([A-Z_]+): (.+?)\n```', cont, re.S))   # MERER, CREW, KHUFU, … GLOBAL_LOOK
def ex(s): return re.sub(r'\{([A-Z_]+)\}', lambda m: TOK[m.group(1)], s)

NEG = ('modern clothing, modern buildings, plastic, glass bottles, iron or steel tools, wheels or wheeled carts, horses, camels, '
       'reed pen, quill, Roman or Greek columns, temples in the background, extra fingers, extra limbs, deformed hands, duplicated faces, '
       'floating objects, text, letters, captions, watermark, logo, cartoon, anime, plastic CGI look, oversaturated colours')

