md = ['# 06 — Scene sheets (copy-ready prompts)\n',
      'Prompts are **tool-agnostic** (5–8 s clips). Continuity strings from 04 are already expanded in each prompt. ',
      'Text, maps and timelines are added in the edit, not generated. Default negative prompt for every AI scene:\n',
      f'```\n{NEG}\n```\n']
rows = []
for s in S:
    img, vid = ex(s['img']), ex(s['vid'])
    md += [f"## {s['id']} · {s['tc']} · {s['dur']} s\n",
           f"**Narration:** {s['vo']}\n", f"**Subtitles:**\n```\n{s['sub']}\n```\n",
           f"**Visual:** {s['vis']}\n", f"**Image prompt:**\n```\n{img}\n```\n", f"**Video prompt:**\n```\n{vid}\n```\n",
           f"**Camera, depth and parallax:** {s['cam']}\n", f"**Lighting, atmosphere, colour:** {s['light']}\n",
           f"**Sound and music:** {s['sfx']}\n", f"**Transition:** {s['trans']}\n",
           f"**Negative prompt:** default (above)\n", f"**Continuity warnings:** {ex(s['warn'])}\n", '---\n']
    rows.append([s['id'], s['tc'], s['dur'], s['vo'], s['sub'].replace('\n', ' / '), img, vid, s['cam'], s['light'], s['sfx'], s['trans'], NEG, ex(s['warn'])])
(HERE / '06-scenes.md').write_text('\n'.join(md))
with open(HERE / 'prompts.csv', 'w', newline='') as f:
    w = csv.writer(f); w.writerow(['scene', 'timecode', 'seconds', 'narration', 'subtitles', 'image_prompt', 'video_prompt', 'camera', 'light', 'sound', 'transition', 'negative', 'continuity'])
    w.writerows(rows)
print(len(S), 'scenes,', sum(s['dur'] for s in S), 's; tokens:', sorted(TOK))
